#!/usr/bin/env bats

load helpers/common

# CFBundleExecutable is attacker-controlled. App protection hands the name to
# pgrep/pkill, which read their argument as an ERE, so a crafted `.*` that is
# not escaped matches nearly every process and turns the uninstall kill ladder
# into a machine-wide signal. These cases pin the literal-name contract for the
# kill ladder, the wait helper, the preview probe, and the rejection of names
# that cannot be probed safely.

setup_file() {
	mole_test_setup_home uninstall-process-pattern
}

teardown_file() {
	mole_test_teardown_home
}

setup() {
	if [[ "$HOME" != "${BATS_TEST_DIRNAME}/tmp-"* ]]; then
		printf 'FATAL: HOME is not a test temp dir: %s\n' "$HOME" >&2
		return 1
	fi
	export TERM="dumb"
	rm -rf "${HOME:?}"/*
	mkdir -p "$HOME"
}

# A bundle whose CFBundleExecutable holds the test-supplied value, with a real
# Info.plist so force_kill_app reads it exactly the way it reads a shipped app.
make_app_fixture() {
	local app_path="$1" exec_name="$2" bundle_id="$3"
	mkdir -p "$app_path/Contents"
	cat > "$app_path/Contents/Info.plist" << PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>CFBundleExecutable</key><string>${exec_name}</string>
  <key>CFBundleIdentifier</key><string>${bundle_id}</string>
</dict></plist>
PLIST
}

@test "force_kill_app probes and kills a crafted CFBundleExecutable as a literal" {
	local app="$HOME/Applications/Probe.app"
	make_app_fixture "$app" '.*' 'com.example.Probe'

	run env HOME="$HOME" PROJECT_ROOT="$PROJECT_ROOT" MOLE_TEST_NO_AUTH=1 /bin/bash --noprofile --norc << 'EOF'
set -euo pipefail
source "$PROJECT_ROOT/lib/core/common.sh"

# Emulate real pgrep -x: an unescaped `.*` matches, the literal `\.\*` does
# not. A probe that reaches the wildcard is the regression this case punishes.
pgrep() {
	printf 'PGREP:%s\n' "$*" >> "$HOME/process.log"
	case "$*" in
		*'.*'*) return 0 ;;
	esac
	return 1
}
# A real pkill would signal nearly every process on the Mac, so only this stub
# may ever be reached; it records the ladder instead of sending anything.
pkill() {
	printf 'PKILL:%s\n' "$*" >> "$HOME/process.log"
	return 0
}
sleep() { :; }

rc=0
force_kill_app "Probe" "$HOME/Applications/Probe.app" || rc=$?
printf 'force-kill-rc:%s\n' "$rc"
EOF

	[ "$status" -eq 0 ] || { echo "$output"; return 1; }
	[[ "$output" == *"force-kill-rc:0"* ]] || {
		echo "force_kill_app treated the crafted name as a live wildcard: $output"
		cat "$HOME/process.log"
		return 1
	}
	grep -Fq 'PGREP:-x \.\*' "$HOME/process.log" || {
		echo "escaped literal probe missing"
		cat "$HOME/process.log"
		return 1
	}
	! grep -Fq 'PGREP:-x .*' "$HOME/process.log" || {
		echo "unescaped wildcard reached pgrep"
		cat "$HOME/process.log"
		return 1
	}
	! grep -q '^PKILL:' "$HOME/process.log" || {
		echo "kill ladder ran for a name no process matched"
		cat "$HOME/process.log"
		return 1
	}
}

@test "force_kill_app still matches a normal CFBundleExecutable exactly" {
	local app="$HOME/Applications/NormalApp.app"
	make_app_fixture "$app" 'NormalApp' 'com.example.NormalApp'

	run env HOME="$HOME" PROJECT_ROOT="$PROJECT_ROOT" MOLE_TEST_NO_AUTH=1 /bin/bash --noprofile --norc << 'EOF'
set -euo pipefail
source "$PROJECT_ROOT/lib/core/common.sh"

# Only the literal normalized name matches, and it stops matching once the
# SIGTERM rung lands so the ladder exits after one signal.
running=1
pgrep() {
	printf 'PGREP:%s\n' "$*" >> "$HOME/process.log"
	[[ "$running" == "1" && "$*" == "-x NormalApp" ]] && return 0
	return 1
}
pkill() {
	printf 'PKILL:%s\n' "$*" >> "$HOME/process.log"
	[[ "$*" == "-x NormalApp" ]] || return 97
	running=0
	return 0
}
sleep() { :; }

force_kill_app "NormalApp" "$HOME/Applications/NormalApp.app" || exit 1
printf 'normal-exit:%s\n' "$running"
EOF

	[ "$status" -eq 0 ] || { echo "$output"; return 1; }
	[[ "$output" == *"normal-exit:0"* ]] || { echo "$output"; cat "$HOME/process.log"; return 1; }
	grep -Fq 'PGREP:-x NormalApp' "$HOME/process.log" || {
		echo "normal name was not probed as itself"
		cat "$HOME/process.log"
		return 1
	}
	grep -Fq 'PKILL:-x NormalApp' "$HOME/process.log" || {
		echo "normal name did not reach the SIGTERM rung"
		cat "$HOME/process.log"
		return 1
	}
	! grep -Fq 'PKILL:-9 -x NormalApp' "$HOME/process.log" || {
		echo "normal name escalated after SIGTERM landed"
		cat "$HOME/process.log"
		return 1
	}
}

@test "uninstall preview probes the executable name as a literal" {
	run env HOME="$HOME" PROJECT_ROOT="$PROJECT_ROOT" MOLE_TEST_NO_AUTH=1 /bin/bash --noprofile --norc << 'EOF'
set -euo pipefail
source "$PROJECT_ROOT/lib/core/common.sh"
source "$PROJECT_ROOT/lib/uninstall/batch.sh"

pgrep() {
	printf 'PGREP:%s\n' "$*" >> "$HOME/process.log"
	case "$*" in
		*'.*'*) return 0 ;;
		'-qx NormalApp') return 0 ;;
	esac
	return 1
}
pkill() { printf 'PKILL:%s\n' "$*" >> "$HOME/process.log"; return 97; }

# The wildcard must miss (no process is literally named `.*`) while the
# escaped literal is the pattern the preview hands pgrep.
attacker_rc=0
_uninstall_app_running_by_executable "Probe" '.*' || attacker_rc=$?
[[ "$attacker_rc" -eq 1 ]] || exit 1
grep -Fq 'PGREP:-qx \.\*' "$HOME/process.log" || exit 1
! grep -Fq 'PGREP:-qx .*' "$HOME/process.log" || exit 1
! grep -q '^PKILL:' "$HOME/process.log" || exit 1

# A normal name still matches through the same preview probe.
normal_rc=0
_uninstall_app_running_by_executable "NormalApp" 'NormalApp' || normal_rc=$?
[[ "$normal_rc" -eq 0 ]] || exit 1
grep -Fq 'PGREP:-qx NormalApp' "$HOME/process.log" || exit 1

printf 'preview-probe:literal\n'
EOF

	[ "$status" -eq 0 ] || { echo "$output"; cat "$HOME/process.log"; return 1; }
	[[ "$output" == *"preview-probe:literal"* ]] || { echo "$output"; cat "$HOME/process.log"; return 1; }
}

@test "process pattern helper rejects empty and control-byte names" {
	run env PROJECT_ROOT="$PROJECT_ROOT" /bin/bash --noprofile --norc << 'EOF'
set -euo pipefail
source "$PROJECT_ROOT/lib/core/common.sh"

[[ "$(_mole_process_pattern_literal '.*')" == '\.\*' ]] || exit 1
[[ "$(_mole_process_pattern_literal 'NormalApp')" == 'NormalApp' ]] || exit 1

empty_rc=0
_mole_process_pattern_literal "" > /dev/null || empty_rc=$?
[[ "$empty_rc" -ne 0 ]] || exit 1

tab_rc=0
_mole_process_pattern_literal $'bad\tname' > /dev/null || tab_rc=$?
[[ "$tab_rc" -ne 0 ]] || exit 1

newline_rc=0
_mole_process_pattern_literal $'bad\nname' > /dev/null || newline_rc=$?
[[ "$newline_rc" -ne 0 ]] || exit 1

printf 'pattern-helper:guarded\n'
EOF

	[ "$status" -eq 0 ] || { echo "$output"; return 1; }
	[[ "$output" == *"pattern-helper:guarded"* ]] || { echo "$output"; return 1; }
}

#!/usr/bin/env bats

load helpers/common

setup() {
    mole_test_setup_project_root
    export HOME="$BATS_TEST_TMPDIR/home"
    mkdir -p "$HOME"
    export KEYS_FILE="$BATS_TEST_TMPDIR/keys"
    export KEY_STATE="$BATS_TEST_TMPDIR/key-state"
    export MENU_OUTPUT="$BATS_TEST_TMPDIR/menu-output"
}

run_selector() {
    printf '%s\n' "$@" > "$KEYS_FILE"
    run env TERM=xterm-256color MOLE_TEST_NO_AUTH=1 COLUMNS="${COLUMNS:-80}" \
        /bin/bash "$PROJECT_ROOT/tests/fixtures/uninstall_menu.sh"
    [ "$status" -eq 0 ] || { echo "$output"; return 1; }
}

@test "uninstall name sorting works in both directions without metadata" {
    run_selector CHAR:s ENTER
    [[ "$output" == *"SELECTED=/fixture/Alpha.app"* ]] || return 1
    [[ "$output" == *"SORT=name REVERSE=false"* ]] || return 1

    : > "$KEY_STATE"
    run_selector CHAR:o ENTER
    [[ "$output" == *"SELECTED=/fixture/Zebra.app"* ]] || return 1
    [[ "$output" == *"SORT=name REVERSE=true"* ]] || return 1
}

@test "uninstall sorts full app names when their displayed prefixes match" {
    export WITH_METADATA=1 COLUMNS=40
    run_selector CHAR:s DOWN ENTER
    [[ "$output" == *"SELECTED=/fixture/LongAlpha.app"* ]] || return 1
}

@test "uninstall search applies multiword names before confirming selection" {
    run_selector CHAR:/ CHAR:v CHAR:I CHAR:s CHAR:u CHAR:a CHAR:l SPACE CHAR:s CHAR:t CHAR:u CHAR:d CHAR:i CHAR:o ENTER ENTER
    [[ "$output" == *"KEYS=16"* ]] || return 1
    [[ "$output" == *"SELECTED=/fixture/Studio.app"* ]] || return 1
}

@test "uninstall search treats punctuation literally and renders percent signs safely" {
    run_selector CHAR:/ 'CHAR:[' CHAR:1 CHAR:0 CHAR:0 CHAR:% 'CHAR:]' ENTER ENTER
    [[ "$output" == *"SELECTED=/fixture/Alpha.app"* ]] || return 1
    [[ "$output" == *"KEYS=9"* ]] || return 1
    run cat "$MENU_OUTPUT"
    [[ "$output" == *'/ Search: [100%]'* ]] || return 1
    [[ "$output" != *'invalid format'* ]] || return 1
}

@test "uninstall search header keeps the end of a long query visible" {
    COLUMNS=40 run_selector CHAR:/ CHAR:a CHAR:b CHAR:c CHAR:d CHAR:e CHAR:f CHAR:g CHAR:h CHAR:i \
        CHAR:j CHAR:k CHAR:l CHAR:m CHAR:n CHAR:o CHAR:p CHAR:q ENTER
    run cat "$MENU_OUTPUT"
    # 40 columns leave 11 for "(0/5; 0 selected)" plus the query: "..." and 8 characters.
    [[ "$output" == *'/ Search: ...jklmnopq'$'\033'* ]] || return 1
    [[ "$output" != *'/ Search: abcdefgh...'* ]] || return 1
}

@test "uninstall preserves selected app identities across sorting and searching" {
    run_selector CHAR:s SPACE CHAR:o CHAR:/ CHAR:v CHAR:i CHAR:s ENTER SPACE QUIT ENTER
    [[ "$output" == *"SELECTED=/fixture/Alpha.app"* ]] || return 1
    [[ "$output" == *"SELECTED=/fixture/Studio.app"* ]] || return 1
    [[ "$output" != *"SELECTED=/fixture/Zebra.app"* ]] || return 1
    [[ "$output" == *"KEYS=11"* ]] || return 1
}

@test "uninstall can sort applied search results without adding to the query" {
    run_selector CHAR:/ CHAR:s CHAR:a CHAR:m CHAR:e ENTER CHAR:o ENTER
    [[ "$output" == *"SELECTED=/fixture/LongZulu.app"* ]] || return 1
    [[ "$output" == *"KEYS=8"* ]] || return 1
}

@test "uninstall search can recover from no matches and backspace to an empty query" {
    run_selector CHAR:/ CHAR:~ ENTER QUIT CHAR:/ CHAR:z DELETE CHAR:v CHAR:i ENTER ENTER
    [[ "$output" == *"SELECTED=/fixture/Studio.app"* ]] || return 1
    [[ "$output" == *"KEYS=11"* ]] || return 1
    run cat "$MENU_OUTPUT"
    [[ "$output" == *"No matches"* ]] || return 1
}

@test "uninstall cannot submit hidden selections from an empty search result" {
    run_selector CHAR:s SPACE CHAR:/ CHAR:~ ENTER ENTER ENTER
    [[ "$output" == *"SELECTED=/fixture/Alpha.app"* ]] || return 1
    [[ "$output" == *"KEYS=7"* ]] || return 1
}

@test "uninstall Enter clears a search that hides selections instead of submitting" {
    # Alpha is selected, then hidden by a search that still shows Studio.
    run_selector CHAR:s SPACE CHAR:/ CHAR:v CHAR:i CHAR:s ENTER ENTER ENTER
    [[ "$output" == *"KEYS=9"* ]] || return 1
    [[ "$output" == *"SELECTED=/fixture/Alpha.app"* ]] || return 1
    [[ "$output" != *"SELECTED=/fixture/Studio.app"* ]] || return 1
}

@test "uninstall footer does not offer Q Cancel while a search is applied" {
    run_selector CHAR:/ CHAR:v CHAR:i CHAR:s ENTER
    run cat "$MENU_OUTPUT"
    # Q clears an applied search, so its frame must not label Q as Cancel.
    # Typing frames draw "vis_"; only the applied frame has a color reset here.
    local applied="${output##*Search: vis$'\033'}"
    [[ "$applied" != "$output" ]] || return 1
    applied="${applied%%$'\033[H'*}"
    [[ "$applied" == *"Esc Clear"* ]] || return 1
    [[ "$applied" != *"Q Cancel"* ]] || return 1
}

@test "uninstall footer prioritizes core actions before optional hints" {
    for COLUMNS in 40 54 60 80 120; do
        export COLUMNS
        : > "$KEY_STATE"
        run_selector CHAR:s QUIT
        run cat "$MENU_OUTPUT"
        [[ "$output" == *"Space Select"* ]] || return 1
        [[ "$output" == *"Enter Save"* ]] || return 1
        [[ "$output" == *"Q Cancel"* ]] || return 1
        if ((COLUMNS >= 47)); then
            [[ "$output" == *"/ Search"* ]] || return 1
        else
            [[ "$output" != *"/ Search"* ]] || return 1
        fi
        if ((COLUMNS >= 56)); then
            [[ "$output" == *"S Name"* ]] || return 1
        else
            [[ "$output" != *"S Name"* ]] || return 1
        fi
        if ((COLUMNS >= 80)); then
            [[ "$output" == *"O A-Z"* ]] || return 1
        else
            [[ "$output" != *"O A-Z"* ]] || return 1
        fi
    done
}

@test "uninstall keyboard input and narrow layouts work in a real terminal" {
    command -v python3 > /dev/null 2>&1 || skip "python3 is required for the PTY fixture"
    run python3 "$PROJECT_ROOT/tests/uninstall_menu_pty.py"
    [ "$status" -eq 0 ] || { echo "$output"; return 1; }
    [[ "$output" == *"PASS: A-Z/Z-A"* ]] || return 1
}

@test "leaving the uninstall screen stops the Preparing app list spinner" {
    if ! /usr/bin/script -q /dev/null /usr/bin/true < /dev/null > /dev/null 2>&1; then
        skip "script cannot allocate a TTY in this environment"
    fi
    local stop_fn="$BATS_TEST_TMPDIR/stop_screen.sh"
    sed -n '/^stop_uninstall_interactive_screen() {$/,/^}$/p' "$PROJECT_ROOT/bin/uninstall.sh" > "$stop_fn"
    [ -s "$stop_fn" ] || return 1

    local raw="$BATS_TEST_TMPDIR/spinner-stop.raw"
    # shellcheck disable=SC2016  # inner bash expands these from its environment
    PROJECT_ROOT="$PROJECT_ROOT" HOME="$HOME" TERM=xterm-256color STOP_FN="$stop_fn" \
        /usr/bin/script -q "$raw" /bin/bash --noprofile --norc -c '
            source "$PROJECT_ROOT/lib/core/common.sh"
            source "$STOP_FN"
            MOLE_SPINNER_PREFIX="" start_inline_spinner "Preparing app list..."
            pid="$INLINE_SPINNER_PID"
            [[ -n "$pid" ]] && echo "SPINNER_STARTED"
            /bin/sleep 0.2
            stop_uninstall_interactive_screen
            /bin/sleep 0.1
            if kill -0 "$pid" 2> /dev/null; then
                echo "SPINNER_LEFT_RUNNING"
                kill "$pid" 2> /dev/null
            else
                echo "SPINNER_STOPPED"
            fi
        ' < /dev/null > /dev/null 2>&1 || true

    run cat "$raw"
    [[ "$output" == *"SPINNER_STARTED"* ]] || return 1
    [[ "$output" == *"SPINNER_STOPPED"* ]] || return 1
    [[ "$output" != *"SPINNER_LEFT_RUNNING"* ]]
}

#!/usr/bin/env bats

load helpers/common

setup_file() { mole_test_setup_home uninstall-review; }
teardown_file() { mole_test_teardown_home; }

run_review_fixture() {
    run env HOME="$HOME/$1" PROJECT_ROOT="$PROJECT_ROOT" REVIEW_CHOICE="$1" /bin/bash --noprofile --norc <<'SH'
set -euo pipefail
source "$PROJECT_ROOT/lib/core/common.sh"
source "$PROJECT_ROOT/lib/ui/menu_paginated.sh"
source "$PROJECT_ROOT/lib/uninstall/batch.sh"
cache="$HOME/Library/Caches/com.example.app"
data="$HOME/Library/Application Support/Example"
app="$HOME/Applications/Example.app"
mkdir -p "$cache" "$data" "$app"
encoded=$(printf '%s\n' "$cache" "$data" | base64 | tr -d '\n')
app_details=("Example|$app|com.example.app|12|$encoded||true|false|false|||||none||||")
running_apps=() sudo_apps=() brew_cask_apps=() leftover_notes=()
total_estimated_size=12
get_path_size_kb() { printf '10\n'; }
calculate_total_size() { if [[ -n "$1" ]]; then printf '1\n'; else printf '0\n'; fi; }
drain_pending_input() { :; }
paginated_multi_select() {
    [[ "$*" == *"Application Support/Example"* ]] || return 9
    [[ "${MOLE_PRESELECTED_INDICES:-}" == "" ]] || return 9
    MOLE_SELECTION_RESULT=""
    [[ "$REVIEW_CHOICE" != selected ]] || MOLE_SELECTION_RESULT=0
    return 0
}
if [[ "$REVIEW_CHOICE" == default ]]; then input=$'\n'; else input=$'d\n'; fi
MOLE_DRY_RUN=1 MOLE_TEST_MODE=1 _batch_preview_and_confirm <<< "$input"
IFS='|' read -r _ _ _ _ result _ <<< "${app_details[0]}"
files=$(decode_file_list "$result" Example)
[[ "$files" == *"$cache"* ]] || exit 1
if [[ "$REVIEW_CHOICE" == selected ]]; then
    [[ "$files" == *"$data"* ]] || exit 1
else
    [[ "$files" != *"$data"* ]] || exit 1
fi
[[ -d "$cache" && -d "$data" && -d "$app" ]] || exit 1
SH
    [ "$status" -eq 0 ] || { echo "$output"; return 1; }
}

@test "uninstall preview keeps personal data by default without losing cache targets" { run_review_fixture default; }
@test "uninstall preview includes only explicitly selected personal data" { run_review_fixture selected; }
@test "uninstall personal-data selection can remain empty" { run_review_fixture empty; }

@test "configuration hints match removed paths and expose no configuration contents" {
    run env HOME="$HOME/config-references" PROJECT_ROOT="$PROJECT_ROOT" /bin/bash --noprofile --norc <<'SH'
set -euo pipefail
source "$PROJECT_ROOT/lib/uninstall/batch.sh"
mkdir -p "$HOME/.cursor" "$HOME/.config/paseo" "$HOME/.config/fish"
app="$HOME/Applications/Example.app"
removed="$HOME/.config/removed-tool"
# shellcheck disable=SC2016  # Literal forms stored by third-party installers.
printf '%s\n' 'alias example=Example' 'TOKEN=[REDACTED]' \
    "TOKEN=[REDACTED] command=\"$app/Contents/MacOS/example\"" \
    "command=\"${app}Helper/run\"" \
    'hook="$HOME/.config/removed-tool/run"' \
    'hook="${HOME}/.config/removed-tool/run"' \
    'hook="~/.config/removed-tool/run"' > "$HOME/.zshrc"
printf '{"command":"%s/Contents/MacOS/example"}\n' "$app" > "$HOME/.cursor/mcp.json"
printf '%s\n' "set -gx EXAMPLE_BIN \"$app/Contents/MacOS/example\"" > "$HOME/.config/fish/config.fish"
cp "$HOME/.zshrc" "$HOME/config-before"
uninstall_configuration_references "$app" "$removed" "$HOME/.config/paseo"
cmp "$HOME/.zshrc" "$HOME/config-before" || exit 1
SH
    [ "$status" -eq 0 ] || { echo "$output"; return 1; }
    [[ "$output" == *"~/.zshrc:3"* && "$output" == *"~/.zshrc:5"* && "$output" == *"~/.zshrc:6"* && "$output" == *"~/.zshrc:7"* ]] || return 1
    [[ "$output" == *"~/.cursor/mcp.json:1"* ]] || return 1
    [[ "$output" == *"~/.config/fish/config.fish:1"* ]] || return 1
    [[ "$output" != *"private-value"* && "$output" != *"~/.zshrc:4"* && "$output" != *"~/.zshrc:1"* ]] || return 1
}

@test "configuration hints keep live owners and skip links binary and oversized files" {
    run env HOME="$HOME/config-protection" PROJECT_ROOT="$PROJECT_ROOT" /bin/bash --noprofile --norc <<'SH'
set -euo pipefail
source "$PROJECT_ROOT/lib/uninstall/batch.sh"
mkdir -p "$HOME/Applications/Live.app" "$HOME/outside" "$HOME/.cursor"
app="$HOME/Applications/Gone.app"
printf '%s\n' "$app/run" > "$HOME/outside/settings"
ln -s "$HOME/outside/settings" "$HOME/.zshrc"
printf '%s\0' "$app/run" > "$HOME/.bashrc"
/usr/bin/perl -e 'print "x" x 1048577' > "$HOME/.profile"
printf '%s\n' "$app/run" >> "$HOME/.profile"
printf '%s\n' "$HOME/Applications/Live.app/run" > "$HOME/.cursor/mcp.json"
uninstall_configuration_references "$app" "$HOME/Applications/Live.app"
SH
    [ "$status" -eq 0 ] || { echo "$output"; return 1; }
    [[ "$output" != *"Configuration references"* ]] || return 1
}

@test "configuration hint failures discard partial output and signals propagate" {
    run env HOME="$HOME/config-timeout" PROJECT_ROOT="$PROJECT_ROOT" /bin/bash --noprofile --norc <<'SH'
set -euo pipefail
source "$PROJECT_ROOT/lib/uninstall/batch.sh"
run_with_timeout() { cat > /dev/null; printf 'PARTIAL_SECRET\n'; return 124; }
uninstall_configuration_references /Applications/Gone.app
run_with_timeout() { cat > /dev/null; return 130; }
rc=0
uninstall_configuration_references /Applications/Gone.app || rc=$?
[[ $rc -eq 130 ]] || exit 1
SH
    [ "$status" -eq 0 ] || { echo "$output"; return 1; }
    [[ "$output" != *"PARTIAL_SECRET"* ]] || return 1
}

@test "uninstall keeps unselected preferences at every post-removal side effect" {
    run env HOME="$HOME/keep-preferences" PROJECT_ROOT="$PROJECT_ROOT" /bin/bash --noprofile --norc <<'SH'
set -euo pipefail
source "$PROJECT_ROOT/lib/uninstall/batch.sh"
source "$PROJECT_ROOT/tests/helpers/uninstall.bash"
mole_test_isolate_uninstall_inventory
app="$HOME/Applications/Example.app"
preferences="$HOME/Library/Preferences/com.example.app.plist"
byhost="$HOME/Library/Preferences/ByHost/com.example.app.fixture.plist"
mkdir -p "$app" "$(dirname "$byhost")"
printf 'settings\n' > "$preferences"
